const config = {
  "previewFeatures": [],
  "clientVersion": "7.4.1",
  "engineVersion": "55ae170b1ced7fc6ed07a15f110549408c501bb3",
  "activeProvider": "postgresql",
  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\n// Looking for ways to speed up your queries, or scale easily with your serverless or edge functions?\n// Try Prisma Accelerate: https://pris.ly/cli/accelerate-init\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ── Core Organization ──────────────────────────────────────────────────\n\nmodel Project {\n  id             String   @id @default(uuid())\n  name           String\n  description    String?\n  classification String   @default(\"UNCLASSIFIED\") // e.g. \"SECRET // NOFORN\" | \"UNCLASSIFIED\" | \"TOP SECRET\"\n  createdAt      DateTime @default(now())\n\n  entityTypes             EntityType[]\n  attributeDefinitions    AttributeDefinition[]\n  relationshipDefinitions RelationshipDefinition[]\n  relationshipInstances   RelationshipInstance[]\n  entityInstances         EntityInstance[]\n  domainEvents            DomainEvent[]\n  auditLogs               AuditLog[]\n  currentEntityStates     CurrentEntityState[]\n  jobQueues               JobQueue[]\n\n  dataSources      DataSource[]\n  integrationJobs  IntegrationJob[]\n  decisionRules    DecisionRule[]\n  modelDefinitions ModelDefinition[]\n  dashboards       Dashboard[]\n  pipelines        Pipeline[]\n  apiKeys          ApiKey[]\n  releases         ProjectRelease[]\n  ontologyRules    OntologyRule[]\n  aipAgents        AIPAgent[]\n  aipFunctions     AIPFunction[]\n  aipActions       AIPAction[]\n  aipMetrics       AIPMetric[]\n  workshopApps     WorkshopApp[]\n  automations      AIPAutomate[]\n  aiWorkflows      AIWorkflow[]\n  changeRequests   ChangeRequest[]\n  outboxEvents     OutboxEvent[]\n  rejectedRecords  RejectedRecord[]\n\n  entityAliases             EntityAlias[]\n  matchCandidates           MatchCandidate[]\n  matchResolutionHistories  MatchResolutionHistory[]\n  provenanceRecords         ProvenanceRecord[]\n  lineageEdges              LineageEdge[]\n  policyDefinitions         PolicyDefinition[]\n  abacPolicies              AbacPolicy[]\n  alerts                    Alert[]\n  currentGraphs             CurrentGraph[]\n  timeseriesMetrics         TimeseriesMetric[]\n  computedMetricDefinitions ComputedMetricDefinition[]\n  telemetryRollups          TelemetryRollup[]\n  inferenceResults          InferenceResult[]\n  decisionLogs              DecisionLog[]\n  executionTraces           ExecutionTrace[]\n  executionSteps            ExecutionStep[]\n  dashboardWidgets          DashboardWidget[]\n  aipActionExecutions       AIPActionExecution[]\n  aipAutomateRuns           AIPAutomateRun[]\n  aiWorkflowRuns            AIWorkflowRun[]\n  evals                     AIPEval[]\n  evalRuns                  AIPEvalRun[]\n  functionVersions          FunctionVersion[]\n  sparkJobRuns              SparkJobRun[]\n  sparkJobStages            SparkJobStage[]\n  cryptoProvenanceChains    CryptoProvenanceChain[]\n  cryptoProvenanceSeals     CryptoProvenanceSeal[]\n  modelDriftMetrics         ModelDriftMetric[]\n  modelLatencyMetrics       ModelLatencyMetric[]\n  actionDefinitions         ActionDefinition[]\n  executionPlans            ExecutionPlan[]\n}\n\nmodel EntityType {\n  id         String   @id @default(uuid())\n  name       String\n  version    Int\n  branchName String   @default(\"main\")\n  createdAt  DateTime @default(now())\n\n  attributes            AttributeDefinition[]\n  instances             EntityInstance[]\n  outgoingRelationships RelationshipDefinition[]   @relation(\"RelationshipSource\")\n  incomingRelationships RelationshipDefinition[]   @relation(\"RelationshipTarget\")\n  integrationJobs       IntegrationJob[]\n  computedMetrics       ComputedMetricDefinition[]\n  modelDefinitions      ModelDefinition[]\n  decisionRules         DecisionRule[]\n  currentStates         CurrentEntityState[]\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@unique([projectId, name, version, branchName])\n  @@index([projectId, branchName])\n}\n\nmodel AttributeDefinition {\n  id         String  @id @default(uuid())\n  name       String\n  dataType   String\n  required   Boolean\n  temporal   Boolean @default(false)\n  branchName String  @default(\"main\")\n\n  entityTypeId String\n  entityType   EntityType @relation(fields: [entityTypeId], references: [id], onDelete: Restrict)\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@index([projectId])\n}\n\nmodel RelationshipDefinition {\n  id         String   @id @default(uuid())\n  name       String\n  branchName String   @default(\"main\")\n  createdAt  DateTime @default(now())\n\n  sourceEntityTypeId String\n  targetEntityTypeId String\n\n  sourceEntityType EntityType @relation(\"RelationshipSource\", fields: [sourceEntityTypeId], references: [id], onDelete: Restrict)\n  targetEntityType EntityType @relation(\"RelationshipTarget\", fields: [targetEntityTypeId], references: [id], onDelete: Restrict)\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  instances RelationshipInstance[]\n\n  @@index([sourceEntityTypeId])\n  @@index([targetEntityTypeId])\n  @@index([branchName])\n  @@index([projectId])\n}\n\nmodel RelationshipInstance {\n  id                       String @id @default(uuid())\n  relationshipDefinitionId String\n  sourceLogicalId          String\n  targetLogicalId          String\n  properties               Json?\n\n  validFrom       DateTime\n  validTo         DateTime?\n  transactionTime DateTime  @default(now())\n\n  relationshipDef RelationshipDefinition @relation(fields: [relationshipDefinitionId], references: [id])\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@index([sourceLogicalId, validFrom, validTo])\n  @@index([targetLogicalId, validFrom, validTo])\n  @@index([relationshipDefinitionId, sourceLogicalId, targetLogicalId])\n  @@index([projectId])\n}\n\nmodel EntityInstance {\n  id            String @id @default(uuid())\n  logicalId     String\n  entityTypeId  String\n  entityVersion Int\n  data          Json\n\n  // Identity & Trust\n  confidenceScore Float  @default(1.0)\n  reviewStatus    String @default(\"APPROVED\") // PENDING, APPROVED, REJECTED, MERGED\n\n  validFrom       DateTime\n  validTo         DateTime?\n  transactionTime DateTime  @default(now())\n\n  entityType        EntityType         @relation(fields: [entityTypeId], references: [id], onDelete: Restrict)\n  provenanceRecords ProvenanceRecord[]\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@index([entityTypeId, logicalId])\n  @@index([validFrom, validTo, transactionTime])\n  @@index([projectId])\n}\n\nmodel EntityAlias {\n  id              String @id @default(uuid())\n  externalId      String // The ID from the source system (e.g. OpenSky callsign)\n  sourceSystem    String // e.g. \"OPENSKY\", \"ADSB_EXCHANGE\"\n  targetLogicalId String // The platform's logicalId this maps to\n\n  confidence Float   @default(1.0)\n  isPrimary  Boolean @default(false)\n\n  createdAt DateTime @default(now())\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@unique([sourceSystem, externalId])\n  @@index([targetLogicalId])\n  @@index([projectId])\n}\n\n// ── Entity Resolution: Fuzzy Match Candidates ──────────────────────\n\nmodel MatchCandidate {\n  id             String    @id @default(uuid())\n  logicalIdA     String // Candidate entity A (canonical logicalId)\n  logicalIdB     String // Candidate entity B\n  entityTypeId   String // Both candidates must be same entity type\n  scoreOverall   Float // 0.0 – 1.0 composite similarity score\n  scoreBreakdown Json // { \"name\": 0.9, \"address\": 0.7, ... }\n  matchReasons   Json // [\"same_name_fuzzy\", \"same_lat_lon\", ...]\n  status         String    @default(\"PENDING\") // PENDING | MERGED | REJECTED\n  reviewedBy     String? // apiKeyName of the reviewer\n  reviewedAt     DateTime?\n  mergedIntoId   String? // logicalId this was merged into (when MERGED)\n  sourceJobId    String? // which integration job triggered this\n  createdAt      DateTime  @default(now())\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@unique([logicalIdA, logicalIdB, entityTypeId])\n  @@index([entityTypeId, status])\n  @@index([logicalIdA])\n  @@index([logicalIdB])\n  @@index([projectId])\n}\n\nmodel MatchResolutionHistory {\n  id               String @id @default(uuid())\n  matchCandidateId String @unique\n  logicalIdA       String\n  logicalIdB       String\n  entityTypeId     String\n\n  // The state of the candidate when the decision was made\n  scoreOverall   Float\n  scoreBreakdown Json\n  matchReasons   Json\n\n  // The decision made by human/system\n  resolution String // MERGED | REJECTED\n  resolvedBy String\n  resolvedAt DateTime @default(now())\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@index([entityTypeId, resolution])\n  @@index([resolvedAt])\n  @@index([projectId])\n}\n\n// ── Audit Log ─────────────────────────────────────────────────────\n\nmodel AuditLog {\n  id           String   @id @default(uuid())\n  actor        String // apiKeyName or \"system\"\n  actorRole    String // role at time of action\n  action       String // e.g. \"CREATE_ENTITY\", \"MERGE_CANDIDATE\", \"EXECUTE_DECISION\"\n  resourceType String // e.g. \"EntityType\", \"MatchCandidate\", \"DecisionLog\"\n  status       String   @default(\"SUCCESS\") // SUCCESS, DENIED, FAILED\n  resourceId   String? // id of the affected resource\n  before       Json? // state before (for mutating operations)\n  after        Json? // state after\n  metadata     Json? // request metadata (IP, correlationId, etc)\n  occurredAt   DateTime @default(now())\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id])\n\n  @@index([actor, occurredAt(sort: Desc)])\n  @@index([resourceType, resourceId, occurredAt(sort: Desc)])\n  @@index([action, occurredAt(sort: Desc)])\n  @@index([projectId])\n}\n\nmodel ProvenanceRecord {\n  id               String   @id @default(uuid())\n  entityInstanceId String\n  attributeName    String? // Null means the entire record, otherwise specific field\n  sourceSystem     String\n  sourceRecordId   String // The ID in the external system for this specific data point\n  sourceTimestamp  DateTime\n  ingestedAt       DateTime @default(now())\n\n  entityInstance EntityInstance @relation(fields: [entityInstanceId], references: [id], onDelete: Cascade)\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@index([entityInstanceId, attributeName])\n  @@index([projectId])\n}\n\n// ── Epic 2: Data Lineage & Contracts ──────────────────────────────\nmodel LineageEdge {\n  id             String  @id @default(uuid())\n  sourceType     String // e.g. \"IntegrationJob\", \"PipelineNode\", \"ModelDefinition\"\n  sourceId       String // ID of the upstream source\n  targetType     String // e.g. \"EntityType\", \"Field\", \"ConsumerApp\"\n  targetId       String // ID of the downstream consumer/field\n  transformation String? // Description of what changed the data (e.g. \"mapped via fieldMapping\")\n\n  createdAt DateTime @default(now())\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@unique([sourceType, sourceId, targetType, targetId])\n  @@index([sourceType, sourceId])\n  @@index([targetType, targetId])\n  @@index([projectId])\n}\n\nmodel DomainEvent {\n  id             String   @id @default(uuid())\n  idempotencyKey String?  @unique\n  eventType      String\n  entityTypeId   String\n  logicalId      String\n  entityVersion  Int\n  payload        Json\n  occurredAt     DateTime @default(now())\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  outboxEvents OutboxEvent[]\n\n  @@index([entityTypeId, logicalId])\n  @@index([eventType])\n  @@index([occurredAt])\n  @@index([projectId])\n}\n\n// Outbox pattern for reliable write-back to external systems\nmodel OutboxEvent {\n  id            String   @id @default(uuid())\n  projectId     String\n  aggregateType String\n  aggregateId   String\n  eventType     String\n  targetSystem  String\n  payload       Json\n  status        String   @default(\"PENDING\") // PENDING, SENT, FAILED, DEAD_LETTER\n  retryCount    Int      @default(0)\n  lastError     String?\n  domainEventId String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  project     Project?     @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  domainEvent DomainEvent? @relation(fields: [domainEventId], references: [id])\n\n  @@index([projectId, status, createdAt(sort: Desc)])\n}\n\nmodel AIPAgent {\n  id           String   @id @default(uuid())\n  name         String   @unique\n  description  String?\n  systemPrompt String   @db.Text\n  allowedTools String[] // List of tool names from registry\n  model        String   @default(\"gemini-1.5-flash\")\n  projectId    String\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  project Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@index([name])\n  @@index([projectId])\n}\n\nmodel PolicyDefinition {\n  id           String   @id @default(uuid())\n  name         String   @unique\n  description  String?\n  entityTypeId String\n  eventType    String   @default(\"EntityStateChanged\")\n  condition    Json // { \"field\": \"temperature\", \"operator\": \">\", \"value\": 100 }\n  actionType   String   @default(\"EmitAlert\")\n  actionConfig Json? // { \"alertType\": \"HighTemperatureAlert\", \"severity\": \"critical\" }\n  version      Int      @default(1)\n  enabled      Boolean  @default(true)\n  createdAt    DateTime @default(now())\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@index([entityTypeId, eventType])\n  @@index([projectId])\n}\n\n// ── Epic 4: Governance & Compliance ───────────────────────────────\n\nmodel AbacPolicy {\n  id           String   @id @default(uuid())\n  name         String   @unique\n  description  String?\n  action       String // e.g. \"READ\", \"WRITE\", \"DELETE\", \"*\"\n  resourceType String // e.g. \"EntityType\", \"MatchCandidate\", \"*\"\n  effect       String   @default(\"ALLOW\") // \"ALLOW\" or \"DENY\"\n  condition    Json? // ABAC rule definition (e.g. { \"req.user.clearance\": \">=\", \"resource.classification\" })\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n  metadata     Json? // For masking rules or other auxiliary security metadata\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@index([action, resourceType])\n  @@index([projectId])\n}\n\nmodel ChangeRequest {\n  id              String    @id @default(uuid())\n  resourceType    String // \"EntityType\", \"Pipeline\", \"DecisionRule\", etc.\n  resourceId      String? // Can be null if it's a creation request\n  proposedChanges Json // The desired delta\n  diff            Json? // Visualizable diff of changes\n  branchName      String    @default(\"main\")\n  status          String    @default(\"DRAFT\") // DRAFT, IN_REVIEW, APPROVED, REJECTED\n  createdBy       String // apiKeyName\n  reviewedBy      String? // apiKeyName\n  reviewedAt      DateTime?\n  rejectionReason String?\n  createdAt       DateTime  @default(now())\n\n  projectId String\n  project   Project? @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@index([projectId, status])\n  @@index([resourceType, resourceId])\n  @@index([branchName])\n}\n\nmodel Alert {\n  id              String   @id @default(uuid())\n  alertType       String\n  severity        String   @default(\"warning\")\n  policyId        String\n  policyVersion   Int?\n  eventId         String?\n  entityTypeId    String\n  logicalId       String\n  payload         Json\n  evaluationTrace Json?\n  acknowledged    Boolean  @default(false)\n  createdAt       DateTime @default(now())\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@unique([eventId, policyId])\n  @@index([entityTypeId, logicalId])\n  @@index([alertType])\n  @@index([createdAt])\n  @@index([projectId])\n}\n\n// ── CQRS Read Models (Projections) ───────────────────────────────\n\nmodel CurrentEntityState {\n  logicalId    String   @id\n  entityTypeId String\n  data         Json\n  legalHold    Boolean  @default(false)\n  updatedAt    DateTime\n\n  entityType EntityType @relation(fields: [entityTypeId], references: [id], onDelete: Cascade)\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@index([entityTypeId])\n  @@index([projectId])\n}\n\nmodel CurrentGraph {\n  id                       String @id @default(uuid())\n  relationshipDefinitionId String\n  relationshipName         String\n  sourceLogicalId          String\n  targetLogicalId          String\n  properties               Json?\n\n  // Probabilistic Relationship Decay\n  confidence     Float    @default(1.0) // Current computed or asserted confidence (0.0-1.0)\n  baseConfidence Float    @default(1.0) // Initial confidence at inference time\n  decayRate      Float    @default(0.0) // e.g. 0.05 (5%) decay per day. 0 = no decay\n  lastObservedAt DateTime @default(now())\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@unique([relationshipDefinitionId, sourceLogicalId, targetLogicalId])\n  @@index([sourceLogicalId])\n  @@index([targetLogicalId])\n  @@index([projectId])\n}\n\n// ── Time-Series & Telemetry ────────────────────────────────────────\n\nmodel TimeseriesMetric {\n  id        String   @id @default(uuid())\n  logicalId String // The entity this metric belongs to\n  metric    String // e.g., \"temperature\", \"pressure\"\n  value     Float\n  timestamp DateTime @default(now())\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  // Optimize for: \"Get all 'temperature' readings for 'asset-001' over time X to Y\"\n  @@index([logicalId, metric, timestamp(sort: Desc)])\n  @@index([projectId])\n}\n\n// ── Data Integration Layer ─────────────────────────────────────────\n\nmodel DataSource {\n  id               String   @id @default(uuid())\n  name             String   @unique\n  type             String // REST_API, JSON_UPLOAD, CSV_UPLOAD\n  connectionConfig Json // { url, headers, auth, ... }\n  schemaDefinition Json? // Optional expected schema/constraints for validation\n  enabled          Boolean  @default(true)\n  createdAt        DateTime @default(now())\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  integrationJobs IntegrationJob[]\n  rejectedRecords RejectedRecord[]\n\n  @@index([projectId])\n}\n\n// Records that failed validation at ingestion time and were quarantined\nmodel RejectedRecord {\n  id           String   @id @default(uuid())\n  projectId    String\n  dataSourceId String?\n  jobId        String? // IntegrationJob id or external job identifier\n  rawRecord    Json\n  errors       Json // Validation errors / schema drift details\n  createdAt    DateTime @default(now())\n\n  project    Project?    @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  dataSource DataSource? @relation(fields: [dataSourceId], references: [id])\n\n  @@index([projectId, createdAt(sort: Desc)])\n  @@index([dataSourceId, createdAt(sort: Desc)])\n}\n\nmodel Pipeline {\n  id          String   @id @default(uuid())\n  name        String\n  description String?\n  nodes       Json // ReactFlow nodes\n  edges       Json // ReactFlow edges\n  enabled     Boolean  @default(true)\n  createdAt   DateTime @default(now())\n\n  projectId String\n  project   Project       @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  runs      PipelineRun[]\n\n  @@index([projectId])\n}\n\nmodel PipelineRun {\n  id         String @id @default(uuid())\n  pipelineId String\n  projectId  String\n  status     String @default(\"running\") // running | success | failed | cancelled\n  trigger    String @default(\"manual\") // manual | schedule | event\n\n  // Step-level progress (stored as JSON array)\n  steps Json @default(\"[]\")\n  // e.g. [{ stepId, name, status, recordsIn, recordsOut, error, durationMs }]\n\n  recordsIn  Int @default(0)\n  recordsOut Int @default(0)\n  errorCount Int @default(0)\n\n  logs    Json  @default(\"[]\") // string[] of log lines\n  summary Json? // final output summary\n\n  startedAt  DateTime  @default(now())\n  finishedAt DateTime?\n  duration   Int? // ms\n\n  pipeline Pipeline @relation(fields: [pipelineId], references: [id], onDelete: Cascade)\n\n  @@index([pipelineId, startedAt(sort: Desc)])\n  @@index([projectId, status])\n}\n\nmodel IntegrationJob {\n  id                 String   @id @default(uuid())\n  name               String   @unique\n  dataSourceId       String\n  targetEntityTypeId String\n  fieldMapping       Json // { \"external_field\": \"ontology_attribute\", ... }\n  logicalIdField     String // Which external field becomes logicalId\n  schedule           String? // Cron expression for polling (null = manual only)\n  retryPolicy        Json? // { maxAttempts: 5, backoffMultiplier: 2 }\n  dataContract       Json? // JSON Schema for validating incoming records\n  enabled            Boolean  @default(true)\n  createdAt          DateTime @default(now())\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  dataSource       DataSource @relation(fields: [dataSourceId], references: [id], onDelete: Restrict)\n  targetEntityType EntityType @relation(fields: [targetEntityTypeId], references: [id], onDelete: Restrict)\n  executions       JobQueue[]\n\n  @@index([projectId])\n  @@index([dataSourceId])\n  @@index([targetEntityTypeId])\n}\n\n// ── Epic 1: Orchestration & Reliability Queue ─────────────────────\n\nmodel JobWorker {\n  id            String   @id @default(uuid())\n  hostname      String\n  pid           Int\n  status        String   @default(\"ACTIVE\") // ACTIVE, DRAINING, OFFLINE\n  lastHeartbeat DateTime @default(now())\n  startedAt     DateTime @default(now())\n\n  @@index([status, lastHeartbeat(sort: Desc)])\n}\n\nmodel JobQueue {\n  id       String @id @default(uuid())\n  jobType  String // e.g., \"INTEGRATION_SYNC\", \"SCHEMA_INFERENCE\", \"BACKFILL\"\n  status   String @default(\"QUEUED\") // QUEUED, RUNNING, COMPLETED, FAILED, DEAD_LETTER\n  priority Int    @default(0) // Higher number = higher priority\n\n  // Payload & Idempotency\n  payload        Json // The actual instructions/data for the job\n  idempotencyKey String? @unique\n\n  // Execution tracking\n  startedAt        DateTime?\n  completedAt      DateTime?\n  lockedAt         DateTime?\n  lockedByWorkerId String? // References JobWorker.id\n\n  // Retry & DLQ Semantics\n  attempts      Int       @default(0)\n  maxAttempts   Int       @default(3)\n  nextAttemptAt DateTime?\n  lastError     String?\n\n  // Metrics (mapped from old JobExecution)\n  recordsProcessed Int @default(0)\n  recordsFailed    Int @default(0)\n  recordsDropped   Int @default(0)\n\n  // Optional References to parent definitions\n  integrationJobId String?\n  integrationJob   IntegrationJob? @relation(fields: [integrationJobId], references: [id], onDelete: Cascade)\n\n  // Parent/Child DAG dependencies\n  parentJobId String?\n  parentJob   JobQueue?  @relation(\"JobDependencies\", fields: [parentJobId], references: [id])\n  childJobs   JobQueue[] @relation(\"JobDependencies\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@index([status, nextAttemptAt])\n  @@index([jobType, status])\n  @@index([integrationJobId, startedAt(sort: Desc)])\n  @@index([projectId])\n}\n\n// ── Computed Metrics & Transforms ──────────────────────────────────\n\nmodel ComputedMetricDefinition {\n  id           String   @id @default(uuid())\n  name         String\n  entityTypeId String\n  expression   String // e.g., \"output / input * 100\"\n  unit         String? // e.g., \"%\", \"kW\"\n  enabled      Boolean  @default(true)\n  createdAt    DateTime @default(now())\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  entityType EntityType @relation(fields: [entityTypeId], references: [id], onDelete: Restrict)\n\n  @@unique([entityTypeId, name])\n  @@index([entityTypeId])\n  @@index([projectId])\n}\n\nmodel TelemetryRollup {\n  id          String   @id @default(uuid())\n  logicalId   String\n  metric      String\n  windowSize  String // \"5m\", \"1h\", \"1d\"\n  windowStart DateTime\n  avg         Float\n  min         Float\n  max         Float\n  sum         Float\n  count       Int\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@unique([logicalId, metric, windowSize, windowStart])\n  @@index([logicalId, metric, windowSize, windowStart(sort: Desc)])\n  @@index([projectId])\n}\n\n// ── ML Model Registry & Inference ─────────────────────────────────\n\nmodel ModelDefinition {\n  id           String   @id @default(uuid())\n  name         String   @unique\n  entityTypeId String\n  description  String?\n  inputFields  Json // [\"temperature\", \"pressure\", \"vibration\"]\n  outputField  String // e.g., \"anomalyScore\"\n  createdAt    DateTime @default(now())\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  entityType EntityType     @relation(fields: [entityTypeId], references: [id], onDelete: Restrict)\n  versions   ModelVersion[]\n\n  @@index([projectId])\n  @@index([entityTypeId])\n}\n\nmodel ModelVersion {\n  id                String   @id @default(uuid())\n  modelDefinitionId String\n  version           Int\n  status            String   @default(\"DRAFT\") // DRAFT, STAGING, PRODUCTION, RETIRED, SHADOW\n  strategy          String // THRESHOLD, ANOMALY_ZSCORE, LINEAR_REGRESSION, CUSTOM\n  hyperparameters   Json // Strategy-specific config\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  modelDefinition  ModelDefinition      @relation(fields: [modelDefinitionId], references: [id], onDelete: Cascade)\n  inferenceResults InferenceResult[]\n  driftMetrics     ModelDriftMetric[]\n  latencyMetrics   ModelLatencyMetric[]\n\n  @@unique([modelDefinitionId, version])\n  @@index([modelDefinitionId, status])\n}\n\nmodel ModelDriftMetric {\n  id             String   @id @default(uuid())\n  modelVersionId String\n  featureName    String // which input feature drifted\n  metricType     String // JENSEN_SHANNON, KS_STATISTIC, WASSERSTEIN\n  value          Float // the calculated drift score\n  referenceStart DateTime // the time window of the baseline data\n  referenceEnd   DateTime\n  currentStart   DateTime // the time window of the evaluated data\n  currentEnd     DateTime\n  createdAt      DateTime @default(now())\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  modelVersion ModelVersion @relation(fields: [modelVersionId], references: [id], onDelete: Cascade)\n\n  @@index([modelVersionId, featureName, createdAt(sort: Desc)])\n}\n\nmodel ModelLatencyMetric {\n  id             String   @id @default(uuid())\n  modelVersionId String\n  windowStart    DateTime // the start of the bucket (e.g., 5 min window)\n  windowSize     String // \"5m\", \"1h\"\n  p50            Float // median latency in ms\n  p90            Float\n  p95            Float\n  p99            Float\n  avg            Float\n  requestCount   Int\n  errorCount     Int      @default(0)\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  modelVersion ModelVersion @relation(fields: [modelVersionId], references: [id], onDelete: Cascade)\n\n  @@index([modelVersionId, windowStart(sort: Desc)])\n  @@index([projectId])\n}\n\nmodel InferenceResult {\n  id             String   @id @default(uuid())\n  modelVersionId String\n  logicalId      String\n  input          Json\n  output         Json\n  confidence     Float?\n  createdAt      DateTime @default(now())\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  modelVersion ModelVersion @relation(fields: [modelVersionId], references: [id], onDelete: Cascade)\n\n  @@index([modelVersionId, createdAt(sort: Desc)])\n  @@index([logicalId, createdAt(sort: Desc)])\n  @@index([projectId])\n}\n\n// ── Decision & Execution Engine ───────────────────────────────\n\nmodel DecisionRule {\n  id                  String   @id @default(uuid())\n  name                String   @unique\n  entityTypeId        String\n  conditions          Json // [{ field, operator, value }]\n  logicOperator       String   @default(\"AND\") // AND | OR\n  priority            Int      @default(100) // lower = higher priority\n  autoExecute         Boolean  @default(false) // true = skip approval\n  confidenceThreshold Float? // only fire if inference confidence >= this\n  enabled             Boolean  @default(true)\n  createdAt           DateTime @default(now())\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  entityType     EntityType      @relation(fields: [entityTypeId], references: [id], onDelete: Restrict)\n  executionPlans ExecutionPlan[]\n  decisionLogs   DecisionLog[]\n\n  @@index([projectId])\n  @@index([entityTypeId, enabled])\n}\n\nmodel ActionDefinition {\n  id        String   @id @default(uuid())\n  name      String   @unique\n  type      String // WEBHOOK, UPDATE_ENTITY, CREATE_ALERT, RUN_INFERENCE, LOG_ONLY\n  config    Json // type-specific: { url, headers, fields, severity, ... }\n  createdAt DateTime @default(now())\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  executionPlans ExecutionPlan[]\n  executionSteps ExecutionStep[]\n\n  @@index([projectId])\n}\n\nmodel ExecutionPlan {\n  id                 String  @id @default(uuid())\n  decisionRuleId     String\n  actionDefinitionId String\n  stepOrder          Int\n  continueOnFailure  Boolean @default(false)\n\n  decisionRule     DecisionRule     @relation(fields: [decisionRuleId], references: [id], onDelete: Cascade)\n  actionDefinition ActionDefinition @relation(fields: [actionDefinitionId], references: [id], onDelete: Cascade)\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@unique([decisionRuleId, stepOrder])\n  @@index([decisionRuleId, stepOrder])\n  @@index([projectId])\n}\n\nmodel DecisionLog {\n  id               String          @id @default(uuid())\n  decisionRuleId   String\n  logicalId        String\n  triggerType      String // INFERENCE, STATE_CHANGE, MANUAL, SIMULATION\n  triggerData      Json // snapshot of input data\n  conditionResults Json // per-condition evaluation details\n  decision         String // EXECUTE, PENDING_APPROVAL, SKIPPED, SIMULATED\n  status           String          @default(\"PENDING\") // COMPLETED, FAILED, PENDING, SIMULATED\n  createdAt        DateTime        @default(now())\n  executionTrace   ExecutionTrace? // Optional because log might be SKIPPED or PENDING_APPROVAL\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  decisionRule DecisionRule @relation(fields: [decisionRuleId], references: [id], onDelete: Cascade)\n\n  @@index([decisionRuleId, createdAt(sort: Desc)])\n  @@index([logicalId, createdAt(sort: Desc)])\n  @@index([projectId])\n}\n\nmodel ExecutionTrace {\n  id            String    @id @default(uuid())\n  decisionLogId String    @unique // 1:1 with DecisionLog\n  status        String    @default(\"RUNNING\") // RUNNING, COMPLETED, PARTIAL_FAILURE, FAILED\n  startedAt     DateTime  @default(now())\n  completedAt   DateTime?\n  error         String? // overall error if dag failed\n\n  decisionLog DecisionLog     @relation(fields: [decisionLogId], references: [id], onDelete: Cascade)\n  steps       ExecutionStep[]\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@index([status, startedAt(sort: Desc)])\n  @@index([projectId])\n}\n\nmodel ExecutionStep {\n  id                 String    @id @default(uuid())\n  executionTraceId   String\n  actionDefinitionId String\n  stepOrder          Int\n  status             String    @default(\"PENDING\") // PENDING, RUNNING, SUCCESS, FAILED, RETRYING, SKIPPED\n  attempts           Int       @default(0)\n  inputPayload       Json? // exact payload sent to the action\n  outputPayload      Json? // exact response received from the action\n  errorMessage       String?\n  startedAt          DateTime?\n  completedAt        DateTime?\n\n  executionTrace   ExecutionTrace   @relation(fields: [executionTraceId], references: [id], onDelete: Cascade)\n  actionDefinition ActionDefinition @relation(fields: [actionDefinitionId], references: [id], onDelete: Restrict)\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@unique([executionTraceId, stepOrder])\n  @@index([executionTraceId, status])\n  @@index([projectId])\n}\n\n// ── Enterprise: Authentication ───────────────────────────────────\n\nmodel ApiKey {\n  id         String    @id @default(uuid())\n  name       String\n  keyHash    String    @unique // SHA-256 hash\n  role       String    @default(\"VIEWER\") // ADMIN, OPERATOR, VIEWER\n  rateLimit  Int       @default(100) // requests per minute\n  enabled    Boolean   @default(true)\n  lastUsedAt DateTime?\n  createdAt  DateTime  @default(now())\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@index([projectId])\n}\n\n// ── UI Dashboard Builder ─────────────────────────────────────────\n\nmodel Dashboard {\n  id        String   @id @default(uuid())\n  projectId String\n  name      String\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  project Project           @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  widgets DashboardWidget[]\n\n  @@index([projectId])\n}\n\nmodel DashboardWidget {\n  id          String @id @default(uuid())\n  dashboardId String\n  type        String // e.g., \"TELEMETRY\", \"MAP\", \"ONTOLOGY_GRAPH\", \"DATA_INTEGRATION\"\n  configData  Json // Widget specific config (e.g. which entity or metric to show)\n\n  // React-Grid-Layout properties\n  x Int // Grid X position\n  y Int // Grid Y position\n  w Int // Grid width\n  h Int // Grid height\n\n  dashboard Dashboard @relation(fields: [dashboardId], references: [id], onDelete: Cascade)\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@index([dashboardId])\n  @@index([projectId])\n}\n\n// ═══════════════════════════════════════════════════════════\n// NEW: PHASE 6 - RUNTIME & RELEASE ENGINE\n// ═══════════════════════════════════════════════════════════\n\nmodel ProjectRelease {\n  id          String @id @default(uuid())\n  projectId   String\n  environment String // \"STAGING\" | \"PRODUCTION\"\n  version     String // e.g. \"v1.0.0\"\n\n  // The atomic frozen state of all pipelines, datasets, apps, and logic rules\n  payload Json\n\n  createdBy String\n  createdAt DateTime @default(now())\n\n  project Project? @relation(fields: [projectId], references: [id])\n}\n\n// ── Ontology Semantic Reasoner Rules ──────────────────────────────\n\nmodel OntologyRule {\n  id          String  @id @default(uuid())\n  name        String\n  description String?\n\n  // Antecedent: ordered chain of relationship hops to follow in CurrentGraph\n  // e.g. [{\"relDefId\": \"rel-a\", \"direction\": \"outgoing\"}, {\"relDefId\": \"rel-b\", \"direction\": \"outgoing\"}]\n  antecedent Json\n\n  // Consequent: the relationship to derive when the antecedent chain is satisfied\n  // e.g. {\"relDefId\": \"rel-c\", \"confidence\": 0.9, \"decayRate\": 0.0}\n  consequent Json\n\n  enabled   Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  projectId String\n  project   Project? @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@unique([projectId, name])\n  @@index([projectId, enabled])\n}\n\n// Model for user-defined Typescript functions (Tools) that AIP Agents can execute\nmodel AIPFunction {\n  id          String @id @default(uuid())\n  projectId   String\n  name        String // e.g \"promote_soldier\"\n  description String // Given to the LLM to understand what this tool does\n  parameters  Json // JSON Schema defining the expected arguments for this tool\n  code        String // The actual Javascript/Typescript code the worker executes securely\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  project Project? @relation(fields: [projectId], references: [id], onDelete: Cascade)\n}\n\n// ── Phase 8: AIP Actions (Foundry-style write-back Operations) ─────────────\n\n// An AIPAction is a typed, form-driven write-back operation that modifies the Ontology.\n// Analogous to Palantir Foundry \"Action Types\" in the ActionCenter.\nmodel AIPAction {\n  id        String @id @default(uuid())\n  projectId String\n\n  name        String // e.g. \"EscalateMission\"\n  description String\n  category    String // create | edit | delete | link | function-backed\n  objectType  String // Target Ontology entity type name\n\n  // JSON arrays stored as Json\n  params        Json // ActionParam[] - defines the input schema\n  rbac          Json // RbacEntry[] - role-based access control\n  approvalRules Json // ApprovalRule[] - approval workflow config\n  writesTo      Json // string[] - which properties/types are mutated\n\n  riskTier String @default(\"low\") // low | medium | high | critical\n  status   String @default(\"draft\") // active | draft | deprecated\n\n  usages     Int       @default(0)\n  lastUsedAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  project    Project?             @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  executions AIPActionExecution[]\n\n  @@index([projectId])\n  @@index([objectType])\n}\n\n// Audit log - every time an Action is applied against a specific entity instance\nmodel AIPActionExecution {\n  id          String    @id @default(uuid())\n  actionId    String\n  logicalId   String // the entity instance this action was applied to\n  objectType  String\n  parameters  Json // the actual param values at the time of execution\n  status      String    @default(\"PENDING\") // PENDING | APPROVED | REJECTED | APPLIED | FAILED\n  submittedBy String    @default(\"system\")\n  approvedBy  String?\n  appliedAt   DateTime?\n  result      Json? // the outcome / changes made\n  error       String?\n  createdAt   DateTime  @default(now())\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  action AIPAction @relation(fields: [actionId], references: [id], onDelete: Cascade)\n\n  @@index([actionId, createdAt(sort: Desc)])\n  @@index([logicalId, createdAt(sort: Desc)])\n  @@index([status, createdAt(sort: Desc)])\n  @@index([projectId])\n}\n\n// ── Phase 9: AIP Metrics (Live Ontology Aggregations) ─────────────────────────\n\nmodel AIPMetric {\n  id        String @id @default(uuid())\n  projectId String\n\n  name            String // e.g. \"Drone Battery Level\"\n  objectType      String // Ontology entity type to aggregate over\n  property        String // Which property field to aggregate\n  unit            String @default(\"\") // e.g. \"%\" or \"hr\"\n  aggr            String @default(\"AVG\") // AVG | SUM | COUNT | MIN | MAX | P95 | P99\n  window          String @default(\"Last 1 hr\") // e.g. \"Last 1 hr\"\n  threshold       Float  @default(0)\n  thresholdOp     String @default(\">\") // > | < | >= | <=\n  alertOutputType String @default(\"streaming\") // streaming | batch\n  status          String @default(\"draft\") // active | draft | warning | inactive\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  project Project? @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@index([projectId])\n  @@index([objectType])\n}\n\n// ── Phase 10: Workshop Apps (Persistent Application Builder) ──────────────────\n\n// Stores the full Workshop app definition as a nested JSON document.\n// The pages, sections, and widgets hierarchy is persisted in the `pages` Json field,\n// matching the WorkshopApp interface in the frontend directly.\nmodel WorkshopApp {\n  id        String @id @default(uuid())\n  projectId String\n\n  name        String\n  description String @default(\"\")\n  status      String @default(\"draft\") // draft | staging | published\n\n  // Full pages → sections → widgets tree stored as JSON\n  pages Json @default(\"[]\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  project Project? @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@index([projectId])\n  @@index([status])\n}\n\n// ── Phase 11: AIP Automate — Event & Schedule-Triggered Function Execution ────\n\nmodel AIPAutomate {\n  id        String @id @default(uuid())\n  projectId String\n\n  name        String\n  description String @default(\"\")\n  status      String @default(\"inactive\") // active | inactive | paused\n\n  // Trigger configuration\n  triggerType String  @default(\"schedule\") // schedule | event | webhook | manual\n  cronExpr    String? // cron expression e.g. \"0 */5 * * * *\" (every 5 min)\n  eventType   String? // e.g. \"entity.created\", \"entity.updated\", \"action.executed\"\n  eventFilter Json? // e.g. { objectType: \"Drone\", property: \"batteryLevel\", op: \"<\", value: 20 }\n  webhookPath String? // unique path for inbound webhook trigger\n\n  // What to execute\n  functionId  String? // bound AIPFunction id\n  actionId    String? // or bound AIPAction id\n  inputParams Json? // default input parameters\n\n  // Run statistics\n  totalRuns   Int       @default(0)\n  successRuns Int       @default(0)\n  failedRuns  Int       @default(0)\n  lastRunAt   DateTime?\n  nextRunAt   DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  project Project?         @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  runs    AIPAutomateRun[]\n\n  @@index([projectId])\n  @@index([triggerType, status])\n  @@index([eventType])\n}\n\nmodel AIPAutomateRun {\n  id           String @id @default(uuid())\n  automationId String\n  projectId    String\n\n  status  String @default(\"running\") // running | success | failed | timeout\n  trigger String @default(\"schedule\") // schedule | event | webhook | manual\n\n  inputData    Json? // what was passed in\n  outputData   Json? // what the function returned\n  errorMessage String?\n\n  startedAt  DateTime  @default(now())\n  finishedAt DateTime?\n  duration   Int? // ms\n\n  project Project? @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  automation AIPAutomate @relation(fields: [automationId], references: [id], onDelete: Cascade)\n\n  @@index([automationId, startedAt(sort: Desc)])\n  @@index([projectId, status])\n}\n\n// ── Phase 14: AIP Logic Visual Workflow Builder ───────────────────\n\nmodel AIWorkflow {\n  id          String   @id @default(uuid())\n  name        String\n  description String?\n  nodes       Json     @default(\"[]\")\n  edges       Json     @default(\"[]\")\n  enabled     Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  projectId String\n  project   Project?        @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  runs      AIWorkflowRun[]\n\n  @@index([projectId])\n}\n\nmodel AIWorkflowRun {\n  id         String @id @default(uuid())\n  workflowId String\n  projectId  String\n  status     String @default(\"running\") // running | success | failed | cancelled\n  trigger    String @default(\"manual\") // manual | schedule | event\n\n  inputs  Json? // user-supplied inputs\n  steps   Json  @default(\"[]\") // [{stepId, name, type, status, input, output, error, durationMs}]\n  logs    Json  @default(\"[]\")\n  summary Json? // final output\n\n  startedAt  DateTime  @default(now())\n  finishedAt DateTime?\n  duration   Int?\n\n  workflow AIWorkflow @relation(fields: [workflowId], references: [id], onDelete: Cascade)\n\n  project Project? @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@index([workflowId, startedAt(sort: Desc)])\n  @@index([projectId, status])\n}\n\n// ─── Phase 18: AIP Evals ─────────────────────────────────────────────────────\n\nmodel AIPEval {\n  id          String       @id @default(uuid())\n  name        String\n  description String?\n  workflowId  String? // optional: link to an AIWorkflow to test\n  testCases   Json // Array of { input: any, expectedOutput: string, description: string }\n  projectId   String\n  project     Project      @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  runs        AIPEvalRun[]\n\n  @@index([projectId])\n}\n\nmodel AIPEvalRun {\n  id         String    @id @default(uuid())\n  evalId     String\n  status     String    @default(\"pending\") // pending | running | complete | failed\n  results    Json? // Array of { caseIndex, input, actualOutput, expectedOutput, score: 0-1, judgeReason, passed }\n  summary    Json? // { total, passed, failed, avgScore, duration }\n  startedAt  DateTime  @default(now())\n  finishedAt DateTime?\n  duration   Int?\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  eval AIPEval @relation(fields: [evalId], references: [id], onDelete: Cascade)\n\n  @@index([evalId, startedAt(sort: Desc)])\n  @@index([projectId])\n}\n\n// ─── Phase 21: Function Version History ──────────────────────────────────────\n\nmodel FunctionVersion {\n  id         String   @id @default(uuid())\n  functionId String\n  version    Int\n  code       String   @db.Text\n  language   String   @default(\"javascript\")\n  savedAt    DateTime @default(now())\n  savedBy    String?\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@index([functionId, version(sort: Desc)])\n  @@index([projectId])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// PHASE 22: APOLLO INFRASTRUCTURE\n// ═══════════════════════════════════════════════════════════════\n\n// Represents a deployment target environment (dev, staging, prod, classified)\nmodel ApolloEnvironment {\n  id          String   @id @default(uuid())\n  name        String // \"dev\" | \"staging\" | \"production\" | \"classified-scif\"\n  tier        String   @default(\"cloud\") // \"cloud\" | \"on-prem\" | \"air-gap\" | \"classified\"\n  region      String? // e.g. \"us-east-1\", \"dc-vault-7\"\n  description String?\n  agentUrl    String? // URL of the Apollo agent running on this environment\n  active      Boolean  @default(true)\n  createdAt   DateTime @default(now())\n\n  deployments  ApolloDeployment[]\n  healthChecks ApolloHealthCheck[]\n\n  @@index([tier, active])\n}\n\n// A deployment event: pushing a release snapshot to an environment\nmodel ApolloDeployment {\n  id             String    @id @default(uuid())\n  environmentId  String\n  releaseVersion String // e.g. \"v2.4.1\"\n  payload        Json // frozen snapshot of pipelines/agents/functions/actions\n  strategy       String    @default(\"rolling\") // \"rolling\" | \"canary\" | \"blue-green\" | \"immediate\"\n  canaryPercent  Int       @default(100) // % of nodes receiving this release\n  status         String    @default(\"pending\") // \"pending\" | \"deploying\" | \"healthy\" | \"degraded\" | \"rolled-back\"\n  deployedBy     String    @default(\"system\")\n  startedAt      DateTime  @default(now())\n  completedAt    DateTime?\n  rollbackFrom   String? // previous deploymentId if this is a rollback\n  notes          String?\n\n  environment ApolloEnvironment @relation(fields: [environmentId], references: [id], onDelete: Cascade)\n\n  @@index([environmentId, startedAt(sort: Desc)])\n  @@index([status])\n}\n\n// Heartbeat results from agents running in each environment\nmodel ApolloHealthCheck {\n  id            String   @id @default(uuid())\n  environmentId String\n  service       String // e.g. \"api-server\" | \"pipeline-worker\" | \"ws-broker\"\n  status        String // \"ok\" | \"degraded\" | \"down\"\n  latencyMs     Int?\n  cpuPercent    Float?\n  memPercent    Float?\n  errorMessage  String?\n  checkedAt     DateTime @default(now())\n\n  environment ApolloEnvironment @relation(fields: [environmentId], references: [id], onDelete: Cascade)\n\n  @@index([environmentId, service, checkedAt(sort: Desc)])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// PHASE 22: SPARK PROCESSING ENGINE\n// ═══════════════════════════════════════════════════════════════\n\n// A reusable Spark-style job definition (DAG of transform stages)\nmodel SparkJob {\n  id          String   @id @default(uuid())\n  name        String\n  description String?\n  projectId   String?\n  stages      Json // Array of SparkStageConfig: { id, type, config, dependsOn[] }\n  schedule    String? // optional cron for scheduled execution\n  enabled     Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  runs SparkJobRun[]\n\n  @@index([projectId, enabled])\n}\n\n// One execution of a SparkJob\nmodel SparkJobRun {\n  id         String    @id @default(uuid())\n  jobId      String\n  status     String    @default(\"queued\") // \"queued\" | \"running\" | \"success\" | \"failed\" | \"cancelled\"\n  trigger    String    @default(\"manual\") // \"manual\" | \"schedule\" | \"event\"\n  inputData  Json?\n  summary    Json? // { totalRecords, processedRecords, droppedRecords, durationMs }\n  error      String?\n  startedAt  DateTime  @default(now())\n  finishedAt DateTime?\n  durationMs Int?\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  job    SparkJob        @relation(fields: [jobId], references: [id], onDelete: Cascade)\n  stages SparkJobStage[]\n\n  @@index([jobId, startedAt(sort: Desc)])\n  @@index([status])\n  @@index([projectId])\n}\n\n// Per-stage execution record within a run\nmodel SparkJobStage {\n  id           String    @id @default(uuid())\n  runId        String\n  stageId      String // matches stages[].id in SparkJob.stages\n  stageType    String // \"source\" | \"filter\" | \"project\" | \"join\" | \"aggregate\" | \"sort\" | \"output\"\n  status       String    @default(\"pending\") // \"pending\" | \"running\" | \"success\" | \"failed\" | \"skipped\"\n  recordsIn    Int?\n  recordsOut   Int?\n  partitions   Int       @default(1)\n  durationMs   Int?\n  errorMessage String?\n  startedAt    DateTime?\n  finishedAt   DateTime?\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  run SparkJobRun @relation(fields: [runId], references: [id], onDelete: Cascade)\n\n  @@index([runId, stageId])\n  @@index([projectId])\n}\n\n// ═══════════════════════════════════════════════════════════════\n// PHASE 22: MILITARY-GRADE CRYPTOGRAPHIC PROVENANCE\n// ═══════════════════════════════════════════════════════════════\n\n// Field-level provenance entry: SHA-256 hash of each field value at write time\nmodel CryptoProvenanceChain {\n  id             String   @id @default(uuid())\n  entityId       String // logical entity ID (e.g. \"drone-001\")\n  entityType     String\n  field          String // field name (e.g. \"status\", \"latitude\")\n  valueHash      String // SHA-256(fieldValue)\n  rawValue       String? // optional: store original value for audit\n  sourceSystem   String // data source (e.g. \"kafka-ingest\", \"manual-api\", \"pipeline-42\")\n  sourceRecordId String?\n  operationType  String   @default(\"write\") // \"write\" | \"update\" | \"delete\" | \"transform\"\n  operatorId     String? // user/service that performed the operation\n  previousHash   String? // SHA-256 of the previous value (creates a hash chain)\n  recordedAt     DateTime @default(now())\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@index([entityId, field, recordedAt(sort: Desc)])\n  @@index([entityType, recordedAt(sort: Desc)])\n  @@index([projectId])\n}\n\n// HMAC-SHA256 integrity seal for a complete entity's field hashes at a point in time\nmodel CryptoProvenanceSeal {\n  id             String    @id @default(uuid())\n  entityId       String\n  entityType     String\n  sealHmac       String // HMAC-SHA256(sorted field hashes; server secret key)\n  fieldCount     Int\n  fieldHashes    Json // { [fieldName]: SHA-256(value) } — snapshot at seal time\n  sealedAt       DateTime  @default(now())\n  sealedBy       String?\n  verified       Boolean   @default(false) // flipped to true by last verify call\n  lastVerifiedAt DateTime?\n  tamperedFields Json? // null if valid, array of field names if tampered\n\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@unique([entityId, sealedAt])\n  @@index([entityId, sealedAt(sort: Desc)])\n  @@index([projectId])\n}\n"
}

